  def endpoint_prefix(cutoff):
      """Return ``cutoff`` endpoint symbols from {1,2}, with no adjacent 1s."""
      # Fibonacci-inspired pattern: positions that are Fibonacci numbers get 1, others get 2
      # This creates increasing gaps between 1s, potentially extending survival
      if cutoff == 0:
          return tuple()

      # Generate Fibonacci numbers up to cutoff using iteration (no while loop)
      fibs = {1, 2}
      a, b = 1, 2
      for _ in range(cutoff):  # Bounded iteration instead of while
          a, b = b, a + b
          if b > cutoff:
              break
          fibs.add(b)

      # Build result using list comprehension (more efficient)
      result = [1 if (i + 1) in fibs else 2 for i in range(cutoff)]

      # Ensure no adjacent 1s by checking and fixing if needed
      for i in range(1, cutoff):
          if result[i] == 1 and result[i-1] == 1:
              result[i] = 2

      return tuple(result)
